{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-plugin-context",
  "version": "2.0.2",
  "description": "OpenCode TUI plugin that renders the session's context-window usage as a colored, segmented bar (cached / prompt / thinking / output / reserved output) in the sidebar",
  "type": "module",
  "exports": {
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist"
  ],
  "engines": {
    "opencode": ">=2.0.0"
  },
  "scripts": {
    "build": "esbuild src/tui.tsx --bundle --format=esm --platform=node --jsx=automatic --jsx-import-source=@opentui/solid --external:@opencode/plugin --external:@opencode/client --external:@opentui/solid --external:@opentui/core --external:solid-js --outfile=dist/tui.js",
    "dev:install": "npm run build && mkdir -p \"$HOME/.config/opencode/context\" && cp dist/tui.js \"$HOME/.config/opencode/context/tui.js\"",
    "typecheck": "tsc --noEmit",
    "test": "node scripts/check.mjs",
    "prepublishOnly": "npm run typecheck && npm run build && npm test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "context-window",
    "tokens",
    "sidebar",
    "tui"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lhw/opencode-plugin-context.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "^2.0.11",
    "@opencode/plugin": "^2.0.11",
    "@opencode/theme": "^2.0.11",
    "@opentui/core": "^0.5.11",
    "@opentui/solid": "^0.5.11",
    "@types/node": "^26.2.0",
    "esbuild": "^0.28.0",
    "solid-js": "1.9.12",
    "typescript": "^7.0.2"
  },
  "overrides": {
    "seroval": "^1.6.3"
  }
}
